function validate([s, x, y]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (!Number.isInteger(x) || x < 1 || x > 10000) return 'x is an integer from 1 to 10000.';
  if (!Number.isInteger(y) || y < 1 || y > 10000) return 'y is an integer from 1 to 10000.';
  return null;
}

