function maximumGain(s, x, y) {
  let first = 'ab';
  let high = x;
  let low = y;
  if (y > x) {
    first = 'ba';
    high = y;
    low = x;
  }
  const stack = [];
  let score = 0;
  for (const ch of s) {
    if (stack.length > 0 && stack[stack.length - 1] === first[0] && ch === first[1]) {
      stack.pop();
      score += high;
    } else {
      stack.push(ch);
    }
  }
  const rest = [];
  for (const ch of stack) {
    if (rest.length > 0 && rest[rest.length - 1] === first[1] && ch === first[0]) {
      rest.pop();
      score += low;
    } else {
      rest.push(ch);
    }
  }
  return score;
}

