function maximumGain(s, x, y) {
  const memo = new Map();
  const best = (t) => {
    if (memo.has(t)) return memo.get(t);
    let result = 0;
    for (let i = 0; i + 1 < t.length; i++) {
      const pair = t[i] + t[i + 1];
      if (pair !== 'ab' && pair !== 'ba') continue;
      const gain = pair === 'ab' ? x : y;
      result = Math.max(result, gain + best(t.slice(0, i) + t.slice(i + 2)));
    }
    memo.set(t, result);
    return result;
  };
  return best(s);
}

