function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 10);
  const other = rand() < 0.5 ? 0.05 : 0.2;
  let s = '';
  for (let i = 0; i < n; i++) {
    const r = rand();
    if (r < other) s += 'cxyz'[Math.floor(rand() * 4)];
    else s += r < other + (1 - other) / 2 ? 'a' : 'b';
  }
  const top = size === 'large' ? 10000 : 10;
  const x = 1 + Math.floor(rand() * top);
  const y = rand() < 0.15 ? x : 1 + Math.floor(rand() * top);
  return [s, x, y];
}
